import pandas as pd


def run(inputs: dict) -> dict:
    target = inputs["target_snapshot"].copy()
    cdc = inputs["cdc_events"].copy()
    watermark = inputs["watermark"].copy()

    cols = list(target.columns)

    # Determine watermark high_ts (single row expected).
    if watermark.empty:
        high_ts = None
    else:
        high_ts = watermark["high_ts"].iloc[0]

    # Step 1: keep only events strictly after the watermark.
    if high_ts is not None:
        filtered = cdc[cdc["event_ts"] > high_ts]
    else:
        filtered = cdc.copy()

    snapshot = target.set_index("product_id")

    if not filtered.empty:
        # Step 2: per product_id, pick the latest event by (event_ts, event_seq).
        filtered_sorted = filtered.sort_values(
            ["product_id", "event_ts", "event_seq"],
            kind="mergesort",
        )
        latest = filtered_sorted.groupby("product_id", as_index=False).tail(1)

        # Step 3: apply upserts/deletes.
        for _, row in latest.iterrows():
            pid = row["product_id"]
            if row["op"] == "D":
                if pid in snapshot.index:
                    snapshot = snapshot.drop(pid)
            else:
                snapshot.loc[pid, "name"] = row["name"]
                snapshot.loc[pid, "price"] = row["price"]
                snapshot.loc[pid, "last_event_ts"] = row["event_ts"]

    new_snapshot = snapshot.reset_index()

    # Preserve original column order/schema.
    new_snapshot = new_snapshot[cols]

    return {"new_snapshot": new_snapshot}
